-- Add exactly one Culture to the inherited total (do not duplicate base yields).
UPDATE Building_YieldChanges SET Yield=Yield+1 WHERE rowid=(SELECT MIN(rowid) FROM Building_YieldChanges WHERE BuildingType='BUILDING_LANTERN_SIGNAL_LIGHTHOUSE' AND YieldType='YIELD_CULTURE');
 WHERE NOT EXISTS (SELECT 1 FROM Building_YieldChanges WHERE BuildingType='BUILDING_LANTERN_SIGNAL_LIGHTHOUSE' AND YieldType='YIELD_CULTURE');
UPDATE Leader_Flavors SET Flavor=8 WHERE LeaderType='LEADER_LANTERN_MAREN' AND FlavorType IN ('FLAVOR_NAVAL','FLAVOR_NAVAL_RECON','FLAVOR_NAVAL_TILE_IMPROVEMENT','FLAVOR_SCIENCE','FLAVOR_CULTURE','FLAVOR_DEFENSE');
UPDATE Leader_Flavors SET Flavor=3 WHERE LeaderType='LEADER_LANTERN_MAREN' AND FlavorType IN ('FLAVOR_OFFENSE','FLAVOR_EXPANSION');
UPDATE Leader_MajorCivApproachBiases SET Bias=2 WHERE LeaderType='LEADER_LANTERN_MAREN' AND MajorCivApproachType='MAJOR_CIV_APPROACH_WAR';
